+	$(CC) $(CFLAGS) -I. -c -o $@ $<
+
+tests/test_glm_vq_work: tests/test_glm_vq_work.o $(DS4_CUDA_CORE_OBJS)
+	$(NVCC) $(NVCCFLAGS) -o $@ $^ $(CUDA_LDLIBS)
