diff --git a/ds4_glmvq_gpu.cuh b/ds4_glmvq_gpu.cuh
index 19b9c28d..8521016d 100644
--- a/ds4_glmvq_gpu.cuh
+++ b/ds4_glmvq_gpu.cuh
@@ -23,6 +23,8 @@ struct ds4_gvq_model {
 struct ds4_gvq_ctx {
     const ds4_gvq_model *model;
     ds4_gpu_tensor *scratch, *workspace, *pairs;
+    ds4_gpu_tensor *arena = nullptr;
+    uint64_t arena_cursor = 0;
     cublasHandle_t handle;
     cudaStream_t stream;
     glmvq_restore_mode restore;
@@ -62,6 +64,48 @@ static uint64_t gvq_mma_bytes(uint32_t rows) {
     return (uint64_t)rows * GVQ_USED * per_pair;
 }

+static uint64_t gvq_mma_reserve(ds4_gvq_ctx *ctx, uint32_t rows) {
+    const uint64_t bytes = gvq_mma_bytes(rows);
+    if (!bytes) { return 0; }
+    const cudaError_t status[] = {
+        glmvq_mma_prepare<GVQ_MMA_ROWS, GVQ_MMA_TOKENS, GLMVQ_MMA_GATE>(&ctx->mma_blocks[0]),
+        glmvq_mma_prepare<GVQ_MMA_ROWS, GVQ_MMA_TOKENS, GLMVQ_MMA_UP>(&ctx->mma_blocks[1]),
+        glmvq_mma_prepare<GVQ_MMA_ROWS, GVQ_MMA_TOKENS, GLMVQ_MMA_DOWN>(&ctx->mma_blocks[2])
+    };
+    if (status[0] == cudaSuccess && status[1] == cudaSuccess && status[2] == cudaSuccess) { return bytes; }
+    (void)cudaGetLastError();
+    fprintf(stderr, "ds4: GLM VQ MMA resources unavailable; using restore+GEMM\n");
+    return 0;
+}
+
+static uint64_t gvq_decode_reserve(ds4_gvq_ctx *ctx) {
+    const uint64_t bytes = gvq_decode_bytes();
+    if (!bytes) { return 0; }
+    if (glmvq_decode_prepare<13, 32, GLMVQ_DEC_NORMAL>(&ctx->decode_blocks) == cudaSuccess) { return bytes; }
+    (void)cudaGetLastError();
+    fprintf(stderr, "ds4: GLM VQ direct decode resources unavailable; using restore+GEMM\n");
+    return 0;
+}
+
+static bool gvq_arena_span(const uint64_t *sizes, size_t count, uint64_t *bytes) {
+    constexpr uint64_t ALIGN = 256;
+    *bytes = 0;
+    for (size_t i = 0; i < count; i++) {
+        if (!sizes[i]) { continue; }
+        // Preserve CUDA/cuBLAS alignment without inflating the existing quote.
+        if (*bytes % ALIGN || sizes[i] > UINT64_MAX - *bytes) { return false; }
+        *bytes += sizes[i];
+    }
+    return true;
+}
+
+static ds4_gpu_tensor *gvq_work_alloc(ds4_gvq_ctx *ctx, uint64_t bytes) {
+    if (!ctx->arena) { return ds4_gpu_tensor_alloc(bytes); }
+    ds4_gpu_tensor *view = ds4_gpu_tensor_view(ctx->arena, ctx->arena_cursor, bytes);
+    if (view) { ctx->arena_cursor += bytes; }
+    return view;
+}
+
 static bool gvq_span(uint64_t off, uint64_t bytes, uint64_t size) {
     return off <= size && bytes <= size - off;
 }
@@ -188,6 +232,8 @@ extern "C" void ds4_gpu_gvq_free(ds4_gvq_ctx *ctx) {
     ds4_gpu_tensor_free(ctx->pairs);
     ds4_gpu_tensor_free(ctx->workspace);
     ds4_gpu_tensor_free(ctx->scratch);
+    // Views die before their one owner; cuBLAS no longer retains workspace.
+    ds4_gpu_tensor_free(ctx->arena);
     delete ctx;
 }

@@ -213,6 +259,12 @@ extern "C" ds4_gvq_ctx *ds4_gpu_gvq_create(const ds4_gvq_model *model, uint64_t
         fprintf(stderr, "ds4: DS4_GLMVQ_FP8_DIRECT accepts 0 or 1\n");
         return nullptr;
     }
+    const char *arena = getenv("DS4_GLMVQ_WORK_ARENA");
+    if (arena && strcmp(arena, "0") && strcmp(arena, "1")) {
+        fprintf(stderr, "ds4: DS4_GLMVQ_WORK_ARENA accepts 0 or 1\n");
+        return nullptr;
+    }
+    const bool want_arena = arena && !strcmp(arena, "1");
     ds4_gvq_ctx *ctx = new (std::nothrow) ds4_gvq_ctx{};
     if (!ctx) { return nullptr; }
     ctx->direct_fp8 = !fp8 || strcmp(fp8, "0");
@@ -237,9 +289,24 @@ extern "C" ds4_gvq_ctx *ds4_gpu_gvq_create(const ds4_gvq_model *model, uint64_t
         return nullptr;
     }
     ctx->model = model;
-    ctx->scratch = ds4_gpu_tensor_alloc(bytes);
-    ctx->workspace = ds4_gpu_tensor_alloc(GVQ_CUBLAS_WORKSPACE);
-    ctx->pairs = ds4_gpu_tensor_alloc((uint64_t)rows * GVQ_USED * sizeof(uint32_t));
+    uint64_t mma_bytes = 0, decode_bytes = 0;
+    const uint64_t pair_bytes = (uint64_t)rows * GVQ_USED * sizeof(uint32_t);
+    if (want_arena) {
+        // Only reserve supported paths. This session owns every slice until
+        // destruction; no global pool, aliasing or deferred first-touch work.
+        mma_bytes = gvq_mma_reserve(ctx, rows);
+        decode_bytes = gvq_decode_reserve(ctx);
+        const uint64_t sizes[] = {bytes, GVQ_CUBLAS_WORKSPACE, pair_bytes, mma_bytes, decode_bytes};
+        uint64_t total = 0;
+        if (gvq_arena_span(sizes, sizeof(sizes) / sizeof(sizes[0]), &total)) {
+            ctx->arena = ds4_gpu_tensor_alloc(total);
+            if (!ctx->arena) { ds4_gpu_gvq_free(ctx); return nullptr; }
+            fprintf(stderr, "ds4: GLM VQ work arena %.2f MiB\n", (double)total / 1048576.0);
+        }
+    }
+    ctx->scratch = gvq_work_alloc(ctx, bytes);
+    ctx->workspace = gvq_work_alloc(ctx, GVQ_CUBLAS_WORKSPACE);
+    ctx->pairs = gvq_work_alloc(ctx, pair_bytes);
     ctx->routes.resize((uint64_t)rows * GVQ_USED);
     ctx->grouped.resize((uint64_t)rows * GVQ_USED);
     if (!ctx->scratch || !ctx->workspace || !ctx->pairs || !cublas_ok(cublasCreate(&ctx->handle), "GLM VQ cuBLAS create") ||
@@ -248,37 +315,18 @@ extern "C" ds4_gvq_ctx *ds4_gpu_gvq_create(const ds4_gvq_model *model, uint64_t
         ds4_gpu_gvq_free(ctx);
         return nullptr;
     }
-    const uint64_t mma_bytes = gvq_mma_bytes(rows);
+    if (!want_arena) { mma_bytes = gvq_mma_reserve(ctx, rows); }
     if (mma_bytes) {
-        // Reserve before execution/capture; shape/resource failures keep GEMM.
-        const cudaError_t status[] = {
-            glmvq_mma_prepare<GVQ_MMA_ROWS, GVQ_MMA_TOKENS, GLMVQ_MMA_GATE>(&ctx->mma_blocks[0]),
-            glmvq_mma_prepare<GVQ_MMA_ROWS, GVQ_MMA_TOKENS, GLMVQ_MMA_UP>(&ctx->mma_blocks[1]),
-            glmvq_mma_prepare<GVQ_MMA_ROWS, GVQ_MMA_TOKENS, GLMVQ_MMA_DOWN>(&ctx->mma_blocks[2])
-        };
-        if (status[0] == cudaSuccess && status[1] == cudaSuccess && status[2] == cudaSuccess) {
-            ctx->mma = ds4_gpu_tensor_alloc(mma_bytes);
-            if (!ctx->mma) { ds4_gpu_gvq_free(ctx); return nullptr; }
-            ctx->items.reserve((uint64_t)rows * GVQ_USED);
-            ctx->order.resize((uint64_t)rows * GVQ_USED);
-            ctx->token_used.resize(rows);
-        } else {
-            (void)cudaGetLastError();
-            fprintf(stderr, "ds4: GLM VQ MMA resources unavailable; using restore+GEMM\n");
-        }
+        ctx->mma = gvq_work_alloc(ctx, mma_bytes);
+        if (!ctx->mma) { ds4_gpu_gvq_free(ctx); return nullptr; }
+        ctx->items.reserve((uint64_t)rows * GVQ_USED);
+        ctx->order.resize((uint64_t)rows * GVQ_USED);
+        ctx->token_used.resize(rows);
     }
-    const uint64_t decode_bytes = gvq_decode_bytes();
+    if (!want_arena) { decode_bytes = gvq_decode_reserve(ctx); }
     if (decode_bytes) {
-        // The published artifact uses a shared 8192-word E4M3 layer book.
-        // Reserve descriptors and intermediate rows before any execution.
-        const cudaError_t status = glmvq_decode_prepare<13, 32, GLMVQ_DEC_NORMAL>(&ctx->decode_blocks);
-        if (status == cudaSuccess) {
-            ctx->decode = ds4_gpu_tensor_alloc(decode_bytes);
-            if (!ctx->decode) { ds4_gpu_gvq_free(ctx); return nullptr; }
-        } else {
-            (void)cudaGetLastError();
-            fprintf(stderr, "ds4: GLM VQ direct decode resources unavailable; using restore+GEMM\n");
-        }
+        ctx->decode = gvq_work_alloc(ctx, decode_bytes);
+        if (!ctx->decode) { ds4_gpu_gvq_free(ctx); return nullptr; }
     }
     return ctx;
 }

