build.test_source:
/* Exercise session-owned work buffers without loading a model artifact. */
#include "ds4.h"
#include "ds4_gpu.h"
#include "ds4_glmvq.h"
#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <unistd.h>

enum { DIM = 128, ROWS = 4, BF16_TYPE = 30, SCRATCH = 64 * 1024 };

static int check_dot(ds4_gvq_ctx *ctx, ds4_gpu_tensor *input,
        ds4_gpu_tensor *output, uint32_t rows, float value) {
    float x[ROWS * DIM], y[ROWS * DIM];
    const uint64_t bytes = (uint64_t)rows * DIM * sizeof(float);
    for (uint32_t i = 0; i < rows * DIM; i++) { x[i] = value; }
    if (!ds4_gpu_tensor_write(input, 0, x, bytes) ||
        !ds4_gpu_gvq_linear(ctx, output, 0, input, rows, DS4_GVQ_BF16) ||
        !ds4_gpu_tensor_read(output, 0, y, bytes)) { return 0; }

    /* These small binary fractions and sums are exactly representable. */
    for (uint32_t i = 0; i < rows * DIM; i++) {
        if (y[i] != DIM * value) {
            fprintf(stderr, "GLM VQ work: row element %u: %g != %g\n",
                i, y[i], DIM * value);
            return 0;
        }
    }
    return 1;
}

static int check_sessions(const ds4_gvq_model *model) {
    const struct { uint32_t capacity, extra; } cases[] = {
        {1, 0}, {8, 0}, {32, 0}, {512, 0}, {1024, 0}, {2048, 0},
        {32, 1} /* An unaligned scratch size must retain separate allocations. */
    };
    if (setenv("DS4_GLMVQ_WORK_ARENA", "1", 1)) { return 0; }
    ds4_gvq_ctx *keeper = ds4_gpu_gvq_create(model, SCRATCH, 32);
    ds4_gpu_tensor *input = ds4_gpu_tensor_alloc(ROWS * DIM * sizeof(float));
    ds4_gpu_tensor *output = ds4_gpu_tensor_alloc(ROWS * DIM * sizeof(float));
    int ok = keeper && input && output;

    for (unsigned mode = 0; ok && mode < 2; mode++) {
        if (setenv("DS4_GLMVQ_WORK_ARENA", mode ? "1" : "0", 1)) { ok = 0; break; }
        for (unsigned i = 0; ok && i < sizeof(cases) / sizeof(cases[0]); i++) {
            const uint32_t rows = cases[i].capacity < ROWS ? cases[i].capacity : ROWS;
            ds4_gvq_ctx *other = ds4_gpu_gvq_create(model, SCRATCH + cases[i].extra,
                cases[i].capacity);
            ok = other && check_dot(other, input, output, rows, 0.5f) &&
                check_dot(keeper, input, output, ROWS, -0.25f);
            ds4_gpu_gvq_free(other);
            /* Freeing another session must not invalidate this workspace. */
            ok = ok && check_dot(keeper, input, output, ROWS, 0.125f);
            if (!ok) {
                fprintf(stderr, "GLM VQ work: mode=%u capacity=%u extra=%u failed\n",
                    mode, cases[i].capacity, cases[i].extra);
            }
        }
    }
    ds4_gpu_tensor_free(output);
    ds4_gpu_tensor_free(input);
    ds4_gpu_gvq_free(keeper);
    return ok;
}

int main(void) {
    const uint64_t matrix = DIM * DIM * sizeof(uint16_t);
    const uint64_t page = (uint64_t)sysconf(_SC_PAGESIZE);
    const uint64_t bytes = (matrix + page - 1u) / page * page;
    uint16_t *map = mmap(NULL, bytes, PROT_READ | PROT_WRITE,
        MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (map == MAP_FAILED || !ds4_gpu_init()) { return 1; }
    for (unsigned i = 0; i < DIM * DIM; i++) { map[i] = 0x3f80u; }
    if (mprotect(map, bytes, PROT_READ) ||
        ds4_gpu_model_source_bind(map, bytes, DS4_MSRC_ROLE_PRIMARY, -1,
            DS4_RESIDENCY_EAGER_DEVICE, "base", "GVQ work buffers") < 0 ||
        !ds4_gpu_set_model_map_range(map, bytes, 0u, bytes, matrix)) { return 1; }

    ds4_gvq_record record = {0, matrix, BF16_TYPE, DIM, DIM,
        DS4_GVQ_NO_LINK, DS4_GVQ_NO_LINK};
    ds4_unit_tensor_in tensor = {0, matrix, DS4_TCAT_ROUTED_EXPERT, 1u};
    ds4_unit_compile_params params = {0};
    params.max_unit_bytes = bytes;
    params.vmm_granularity = 256u;
    params.device_promote = 1u;
    params.promote_experts = 1u;
    ds4_phys_unit unit;
    const int count = ds4_units_compile(&tensor, 1, &params, &unit);
    uint64_t populated = 0;
    if (count != 1 || ds4_units_verify(&tensor, 1, &params, &unit, count) ||
        ds4_gpu_model_units_bind(map, &unit, count) ||
        !ds4_gpu_materialize_model_plan(map, bytes, &populated)) { return 1; }

    ds4_gvq_model *model = ds4_gpu_gvq_bind(map, bytes, &record, 1);
    const int ok = model && check_sessions(model);
    ds4_gpu_gvq_unbind(model);
    ds4_gpu_unregister_model_map(map);
    ds4_gpu_cleanup();
    munmap(map, bytes);
    printf("GLM VQ work lifetime and independent contexts: %s\n", ok ? "PASS" : "FAIL");
    return ok ? 0 : 1;
}
